function pinyinKey(s){return s.toLowerCase().replace(/u:|v/g,'ü').normalize('NFD').split(/[\s'-]+/).map(x=>{let tone=0;const marks={'\u0304':1,'\u0301':2,'\u030c':3,'\u0300':4};let base=x.replace(/[\u0304\u0301\u030c\u0300]/g,m=>{tone=marks[m];return ''});base=base.replace(/[0-5]/g,m=>{tone=+m;return ''});return base.normalize('NFC')+(tone===5?0:tone)}).join('');}
function dueWords(now=Date.now()){const by=new Map();for(const e of [...state.events].sort((a,b)=>a.time-b.time)){const old=by.get(e.word);const stage=e.ok?Math.min((old?.stage??-1)+1,5):-1;by.set(e.word,{stage,due:e.time+(stage<0?600000:[1,3,7,14,30,60][stage]*86400000)});}return WORDS.filter(w=>by.has(w.id)&&by.get(w.id).due<=now).sort((a,b)=>by.get(a.id).due-by.get(b.id).due);}
const upgradedHome=home;home=function(){upgradedHome();const c=document.createElement('section');c.className='card section';c.innerHTML=`<h2>자동 복습</h2><p>오늘 복습할 단어 ${dueWords().length}개</p><button class="primary full" id="due-start">망각곡선 복습 시작</button><small>정답: 1·3·7·14·30·60일 / 오답: 10분 후</small>`;main.prepend(c);c.querySelector('button').onclick=()=>start(dueWords());};
const upgradedStats=statsPage;statsPage=function(){upgradedStats();const c=document.createElement('section');c.className='card section';c.innerHTML='<h2>학습 통계</h2><select aria-label="기간" id="period"><option value="day">일별 (14일)</option><option value="week">주별 (8주)</option><option value="month">월별 (12개월)</option></select><div id="bars"></div>';main.prepend(c);function draw(){const p=c.querySelector('select').value,n=p==='day'?14:p==='week'?8:12;const end=new Date();end.setHours(0,0,0,0);if(p==='week')end.setDate(end.getDate()-((end.getDay()+6)%7));if(p==='month')end.setDate(1);let rows=[];for(let i=n-1;i>=0;i--){let a=new Date(end),b=new Date(end);if(p==='month'){a.setMonth(a.getMonth()-i);b.setMonth(b.getMonth()-i+1)}else{let k=p==='week'?7:1;a.setDate(a.getDate()-i*k);b.setDate(b.getDate()+(1-i)*k)}let es=state.events.filter(e=>e.time>=+a&&e.time<+b);rows.push([a.toLocaleDateString('ko-KR'),es.length,es.filter(e=>e.ok).length]);}let max=Math.max(1,...rows.map(r=>r[1]));c.querySelector('#bars').innerHTML=rows.map(([d,n,k])=>`<div class="chartrow"><small>${d}</small><div class="charttrack"><div style="width:${n/max*100}%"><i style="width:${n?k/n*100:0}%"></i></div></div><small>${n}회 · ${n?Math.round(k/n*100)+'%':'—'}</small></div>`).join('');}c.querySelector('select').onchange=draw;draw();};
const originalRow=wordRow;wordRow=function(w){return originalRow(w)+`<details class="word-detail"><summary>한자 풀이</summary>${hanjaExplanation(w)||'<p>한국식 훈음 자료 없음</p>'}</details>`};
if('serviceWorker' in navigator && location.protocol==='https:')navigator.serviceWorker.register('./sw.js').catch(console.warn);
render();


