/* Personal settings and favorites: local only */
const prefs33=(()=>{try{return JSON.parse(localStorage.getItem('hsk-prefs33'))||{}}catch{return {}}})();
function savePrefs33(){localStorage.setItem('hsk-prefs33',JSON.stringify(prefs33))}
function applyPrefs33(){document.documentElement.style.colorScheme=prefs33.dark?'dark':'light';document.documentElement.classList.toggle('hsk-dark33',!!prefs33.dark);document.documentElement.style.fontSize=(prefs33.size||100)+'%'}
const css33=document.createElement('style');css33.textContent='.hsk-dark33 body,.hsk-dark33 main{background:#151b19;color:#e8f0eb}.hsk-dark33 .card,.hsk-dark33 .stat,.hsk-dark33 .day,.hsk-dark33 header,.hsk-dark33 nav,.hsk-dark33 input,.hsk-dark33 select,.hsk-dark33 button:not(.primary){background:#26332e;color:#e8f0eb;border-color:#46564e}.fav33{margin:4px}.hsk-dark33 .hero{color:#fff}';document.head.append(css33);applyPrefs33();
function favorites33(){return Array.isArray(prefs33.favorites)?prefs33.favorites:[]}
function toggleFav33(id){const s=new Set(favorites33());s.has(id)?s.delete(id):s.add(id);prefs33.favorites=[...s];savePrefs33()}
const row33=wordRow;wordRow=function(w){return row33(w)+'<button class="fav33" data-fav33="'+w.id+'">'+(favorites33().includes(w.id)?'★ 즐겨찾기':'☆ 즐겨찾기')+'</button>'};
main.addEventListener('click',e=>{const b=e.target.closest('[data-fav33]');if(!b)return;const id=Number(b.dataset.fav33);toggleFav33(id);b.textContent=favorites33().includes(id)?'★ 즐겨찾기':'☆ 즐겨찾기'});
const home33=home;home=function(){home33();const c=document.createElement('section');c.className='card section';const today=new Date().toDateString();const seen=new Set(state.events.map(e=>e.word));const fresh=WORDS.filter(w=>!seen.has(w.id)).slice(0,30);const due=dueWords();c.innerHTML='<h2>오늘의 맞춤 학습</h2><p>신규 '+fresh.length+'개 · 복습 '+due.length+'개</p><button class="primary full" id="plan33">맞춤 학습 시작</button><button class="full" id="favquiz33">즐겨찾기 복습 ('+favorites33().length+')</button><p>오늘 학습 '+state.events.filter(e=>new Date(e.time).toDateString()===today).length+'회</p>';main.prepend(c);c.querySelector('#plan33').onclick=()=>{const a=[...due.slice(0,30),...fresh];if(a.length)start(a);else toast('오늘 학습할 단어가 없습니다.')};c.querySelector('#favquiz33').onclick=()=>{const a=WORDS.filter(w=>favorites33().includes(w.id));if(a.length)start(a);else toast('즐겨찾기 단어가 없습니다.')};};
const stats33=statsPage;statsPage=function(){stats33();const c=document.createElement('section');c.className='card section';const dates=new Set(state.events.map(e=>new Date(e.time).toDateString()));let d=new Date(),streak=0;if(!dates.has(d.toDateString()))d.setDate(d.getDate()-1);while(dates.has(d.toDateString())){streak++;d.setDate(d.getDate()-1)}c.innerHTML='<h2>학습 습관</h2><p>연속 학습 '+streak+'일 · 누적 학습일 '+dates.size+'일</p><h2>화면 설정</h2><label><input type="checkbox" id="dark33"> 다크모드</label><label>글자 크기 <select id="size33"><option value="100">기본</option><option value="115">크게</option><option value="130">매우 크게</option></select></label>';main.prepend(c);const dark=c.querySelector('#dark33'),size=c.querySelector('#size33');dark.checked=!!prefs33.dark;size.value=String(prefs33.size||100);dark.onchange=()=>{prefs33.dark=dark.checked;savePrefs33();applyPrefs33()};size.onchange=()=>{prefs33.size=Number(size.value);savePrefs33();applyPrefs33()};};
render();

